sys_script_include.script:
function MakeTableName(vScope,strSuffix)
{
	strSuffix = GetStringValue(strSuffix);
	if (IsSnakeCase(strSuffix) == false)
	{
		return false;
	}

	var strPrefix = '';

	var grApp = GetAppRecord(vScope);
	if (IsValidRecord(grApp) == true)
	{
		var strScope = GetStringValue(grApp.scope);
		if (strScope == 'global')
		{
			strPrefix = 'u_';
		}
		else
		{
			strPrefix = strScope + '_';
		}
	}
	else if (vScope == 'global')
	{
		strPrefix = 'u_';
	}
	return strPrefix + strSuffix;
}
